#!/usr/bin/perl
# File: lib/User.pl
package User;

use strict;
use warnings;

sub new {
    my ($class, $name, $email) = @_;
    my $self = {
        name  => $name,
        email => $email,
    };
    return bless $self, $class;
}

sub get_name {
    my $self = shift;
    return $self->{name};
}

sub get_email {
    my $self = shift;
    return $self->{email};
}

1;
EOF

